// Age Matrix: filter records exactly 3, 7, or 14 days old today
const TARGET_DAYS = [3, 7, 14];
const portalLink = 'https://sites.google.com/view/portail-temara-mall/accueil';

function toE164MA(raw) {
  if (raw == null || raw === '') return '';
  let phone = String(raw).replace(/[\s\-\(\)\.]/g, '');
  if (!phone) return '';
  if (phone.startsWith('+')) return phone;
  if (phone.startsWith('00')) return '+' + phone.slice(2);
  if (phone.startsWith('212')) return '+' + phone;
  if (phone.startsWith('0')) return '+212' + phone.slice(1);
  return '+212' + phone;
}

function daysSince(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  d.setHours(0, 0, 0, 0);
  return Math.round((today - d) / (24 * 60 * 60 * 1000));
}

const DRIP_COPY = {
  3: {
    sms: 'Bonjour [Nom], votre plan de traitement dentaire est prêt. Nos spécialistes restent disponibles pour répondre à vos questions. Réservez ici : [Link]',
    subject: 'Votre plan de traitement vous attend — J+3',
    body: 'Il y a 3 jours, nous avons préparé votre devis personnalisé. Notre équipe est disponible pour vous accompagner dans votre décision.'
  },
  7: {
    sms: 'Bonjour [Nom], rappel amical : votre plan de soins dentaires est toujours disponible. Prenez rendez-vous pour démarrer votre traitement : [Link]',
    subject: 'Rappel J+7 — Finalisez votre plan de traitement',
    body: 'Une semaine s\'est écoulée depuis votre devis. N\'hésitez pas à nous contacter pour toute question sur votre plan de soins.'
  },
  14: {
    sms: 'Bonjour [Nom], dernière relance : votre plan de traitement dentaire expire bientôt. Sécurisez votre créneau dès maintenant : [Link]',
    subject: 'Dernière relance J+14 — Votre plan de traitement',
    body: 'Deux semaines se sont écoulées. Nous restons à votre disposition pour planifier votre traitement et répondre à toutes vos questions.'
  }
};

const pending = $input.all().filter(item => {
  const status = (item.json['Statut du RDV'] ?? '').toString().trim();
  return status === 'En attente';
});

const cohort = pending.filter(item => {
  const quoteDate = item.json['Date & Heure du RDV'] ?? item.json['Date Devis'] ?? item.json['Date Creation'];
  const age = daysSince(quoteDate);
  return age !== null && TARGET_DAYS.includes(age);
});

return cohort.map(item => {
  const quoteDate = item.json['Date & Heure du RDV'] ?? item.json['Date Devis'] ?? item.json['Date Creation'];
  const age = daysSince(quoteDate);
  const copy = DRIP_COPY[age];
  const nom = item.json['Patient (Nom Complet)'] ?? 'Patient';
  return {
    json: {
      Nom: nom,
      Phone: toE164MA(item.json['Téléphone (WhatsApp)'] ?? ''),
      Email: item.json['Email Contact'] ?? '',
      AgeDays: age,
      Link: portalLink,
      SmsMessage: copy.sms.replace('[Nom]', nom).replace('[Link]', portalLink),
      EmailSubject: copy.subject,
      EmailBody: copy.body
    }
  };
}).filter(item => item.json.Phone);
